Regression focus: the reported defect where a present target is missed.
The suspect code used `while lo < hi`, so once the search window shrank to a
single element (lo == hi) the loop exited *without* checking that element.
Consequently the last element of a two-element list (or the only element of a
one-element list) — i.e. any target that the search is driven to at the
boundary — was reported as absent.

These tests must FAIL against the buggy version and PASS against the fix.
"""

import sys
import unittest
from pathlib import Path

# Make the module under test importable regardless of the cwd the runner
# is invoked from (e.g. `python -m pytest` vs `python -m unittest` at root).
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from bsearch import bsearch  # noqa: E402


class BsearchDefectRegression(unittest.TestCase):
    """Targets the exact class of miss: target found only at the boundary.

    In the buggy loops, none of these are ever compared against `items[mid] ==
    target`, because the window collapses to one element and `lo < hi` stops.
    """

    def test_single_element_list_present(self):
        self.assertEqual(bsearch([5], 5), 0)

    def test_single_element_list_absent_smaller(self):
        self.assertEqual(bsearch([5], 3), -1)

    def test_single_element_list_absent_larger(self):
        self.assertEqual(bsearch([5], 7), -1)

    def test_two_elements_target_is_last(self):
        self.assertEqual(bsearch([1, 3], 3), 1)

    def test_two_elements_target_is_first(self):
        self.assertEqual(bsearch([1, 3], 1), 0)

    def test_two_elements_target_absent(self):
        self.assertEqual(bsearch([1, 3], 2), -1)

    def test_three_elements_target_is_last(self):
        self.assertEqual(bsearch([1, 2, 3], 3), 2)

    def test_three_elements_target_is_first(self):
        self.assertEqual(bsearch([1, 2, 3], 1), 0)

    def test_three_elements_target_is_middle(self):
        self.assertEqual(bsearch([1, 2, 3], 2), 1)


class BsearchGeneral(unittest.TestCase):
    """Sane binary-search behavior for the rest of the contract."""

    def test_empty_list(self):
        self.assertEqual(bsearch([], 1), -1)

    def test_longer_list_every_position(self):
        items = [1, 4, 7, 11, 15, 20, 33]
        for i, value in enumerate(items):
            with self.subTest(i=i, value=value):
                self.assertEqual(bsearch(items, value), i)

    def test_absent_targets(self):
        items = [1, 4, 7, 11, 15, 20, 33]
        for missing in (0, 2, 10, 18, 34, 1 << 30):
            with self.subTest(missing=missing):
                self.assertEqual(bsearch(items, missing), -1)

    def test_duplicates_return_a_valid_index(self):
        items = [2, 2, 2, 5, 5, 9]
        idx = bsearch(items, 5)
        self.assertGreaterEqual(idx, 0)
        self.assertLess(idx, len(items))
        self.assertEqual(items[idx], 5)
        self.assertEqual(bsearch(items, 9), 5)
        self.assertEqual(bsearch(items, 1), -1)

    def test_exhaustive_small_lists(self):
        # for every list size 0..8, every element must be found at its exact
        # index (lists contain distinct values, so the index is unambiguous)
        for n in range(9):
            items = list(range(n))
            for i in range(n):
                with self.subTest(n=n, i=i):
                    self.assertEqual(bsearch(items, i), i)
            # present value (n) is larger than every element, must be -1
            self.assertEqual(bsearch(items, n), -1)

    def test_negative_numbers(self):
        items = [-9, -4, -1, 0, 3, 8]
        for i, value in enumerate(items):
            with self.subTest(i=i, value=value):
                self.assertEqual(bsearch(items, value), i)
        self.assertEqual(bsearch(items, -5), -1)
        self.assertEqual(bsearch(items, 100), -1)


if __name__ == "__main__":
    unittest.main()
